#include <stdio.h>
#include <string.h>
int main(void){
    const char *p="ababc";
    int m=(int)strlen(p);
    int next[16];
    next[1]=0;
    for(int j=1,k=0;j<m;){          /* 1-indexed 王道 next：next[1]=0 */
        if(k==0 || p[j-1]==p[k-1]){ j++; k++; next[j]=k; }
        else k=next[k];
    }
    printf("模式串: %s\n", p);
    printf("位置  :"); for(int i=1;i<=m;i++) printf(" %d",i); printf("\n");
    printf("字符  :"); for(int i=0;i<m;i++) printf(" %c",p[i]); printf("\n");
    printf("next  :"); for(int i=1;i<=m;i++) printf(" %d",next[i]); printf("\n");
    return 0;
}
